1	export type Cell = [x: number, y: number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
8	  const [x, y] = cell;
9	  const [candidateX, candidateY] = candidate;
10	  const isWithinOneStep =
11	    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
12	  return isWithinOneStep && !isSameCell(cell, candidate);
13	}
14	
15	function countNeighbours(cell: Cell, liveCells: Cell[]): number {
16	  return liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
17	}
18	
19	function survives(cell: Cell, liveCells: Cell[]): boolean {
20	  const neighbours = countNeighbours(cell, liveCells);
21	  return neighbours === 2 || neighbours === 3;
22	}
23	
24	function neighboursOf([x, y]: Cell): Cell[] {
25	  const offsets = [-1, 0, 1];
26	  return offsets.flatMap((dx) =>
27	    offsets
28	      .filter((dy) => !(dx === 0 && dy === 0))
29	      .map((dy): Cell => [x + dx, y + dy]),
30	  );
31	}
32	
33	function isAlive(cell: Cell, liveCells: Cell[]): boolean {
34	  return liveCells.some((live) => isSameCell(live, cell));
35	}
36	
37	function isBorn(cell: Cell, liveCells: Cell[]): boolean {
38	  return !isAlive(cell, liveCells) && countNeighbours(cell, liveCells) === 3;
39	}
40	
41	function distinctCells(cells: Cell[]): Cell[] {
42	  return cells.filter(
43	    (cell, index) =>
44	      cells.findIndex((other) => isSameCell(other, cell)) === index,
45	  );
46	}
47	
48	export function nextGeneration(liveCells: Cell[]): Cell[] {
49	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
50	  const births = distinctCells(
51	    liveCells.flatMap(neighboursOf).filter((cell) => isBorn(cell, liveCells)),
52	  );
53	  return [...survivors, ...births];
54	}
